async ({ http: { request }, gh: { api } }) => {
  const [fmt, prs] = await Promise.all([
    request("https://raw.githubusercontent.com/cv/pi-action/main/src/formatting.ts", { maxBytes: 300000 }),
    api("repos/cv/pi-action/pulls?state=all&per_page=8"),
  ]);
  const b = String(fmt.body);
  const lines = b.split("\n");
  const hits = lines.map((l, i) => [i, l] as const).filter(([, l]) => /pit|present|arguments|args/i.test(l)).slice(0, 60).map(([i, l]) => `${i + 1}: ${l}`);
  const p = JSON.parse(prs.stdout).map((x: any) => `${x.number} ${x.state} ${x.head.ref} ${x.title}`);
  return { len: lines.length, hits, p };
}
